_ = input()
s = input()
d = [s[0]]
i = 0
for j, ch in enumerate(s[1:], start=1):
  if ch != s[j - 1]:
    i += (-1) ** (ch > s[j - 1])
    if i < 0:
      d.insert(0, " " * j)
      i = 0
    elif i == len(d):
      d.append(" " * j)
  d[i] = d[i].ljust(j) + ch
for row in d:
  print(row)
